[
  {
    "statement": "In the Mediterranean, prohibiting spearfishing in marine reserves has been associated with higher abundances of targeted fish such as European seabass and gilthead seabream after two to seven years.",
    "citations": [
      "2672"
    ]
  },
  {
    "statement": "Prohibiting spearfishing in Mediterranean marine reserves has been associated with larger sizes of European seabass in protected areas compared to fished areas over similar time frames.",
    "citations": [
      "2672"
    ]
  },
  {
    "statement": "Comparisons between spearfished and non-spearfished areas 10–12 years after implementation reported differences in fish densities related to depth and/or fish size.",
    "citations": [
      "2672"
    ]
  },
  {
    "statement": "Zones within a Mediterranean marine reserve that prohibited spearfishing saw higher commercial and recreational catches of targeted common dentex than zones allowing spearfishing.",
    "citations": [
      "2672"
    ]
  },
  {
    "statement": "Zones within a Mediterranean marine reserve that prohibited spearfishing saw higher commercial and recreational catches of targeted common dentex than areas outside the reserve after one to three years.",
    "citations": [
      "2672"
    ]
  }
]

[
  {
    "statement": "Prohibiting mobile bottom-towed gears dragged across the seafloor was associated with higher total fish biomass after 15 years.",
    "citations": [
      "2673"
    ]
  },
