      "2727",
      "2725",
      "2721"
    ]
  },
  {
    "statement": "Using escape panels, windows, and size-sorting grids in trawl nets improved size-selectivity in multiple studies.",
    "citations": [
      "2727",
      "2725",
      "2721"
    ]
  }
