[
  {
    "statement": "Studies report varied effects of prohibiting all commercial fishing on fish abundance across multiple ocean basins.",
    "citations": []
  },
  {
    "statement": "In the Mediterranean Sea, site comparisons reported no increase in biomass for some targeted species 2–13 years after a commercial fishing closure compared to a fished area.",
    "citations": [
      "2667"
    ]
  },
  {
    "statement": "Other studies in the Mediterranean Sea and additional basins recorded higher abundances for subsets of species, such as some commercially targeted and non-targeted groups.",
    "citations": [
      "2667"
    ]
  },
  {
    "statement": "In the Indian Ocean and Gulf of Mexico, some site comparison studies found higher abundances for parts of the fish community in areas closed to fishing.",
    "citations": [
      "2667"
    ]
  },
  {
    "statement": "Other site comparison studies in the Indian Ocean and Gulf of Mexico reported mixed outcomes across fish species and groups.",
    "citations": [
      "2667"
    ]
  },
  {
    "statement": "In the South Atlantic Ocean, one study found no change in fish species composition in protected areas relative to fished areas.",
    "citations": [
      "2667"
    ]
  },
  {
    "statement": "Abundance-focused comparisons spanning the South Atlantic Ocean and other basins showed responses ranging from higher abundances in some commercially exploited species to mixed effects depending on exploitation history.",
    "citations": [
      "2667"
    ]
  },
  {
    "statement": "In the Tasman Sea, a before-and-after study in an estuary found lower abundances for most species two years after a commercial fishing closure.",
    "citations": [
      "2667"
    ]
  },
  {
    "statement": "Another study in a Tasman Sea reserve zone closed to commercial trapping reported abundance patterns that varied over a decade and among fish groups.",
    "citations": [
      "2667"
    ]
  },
  {
    "statement": "In the South China Sea, overall fish density in the wider region increased within five years after reserves limiting commercial fishing were created.",
    "citations": [
      "2667"
    ]
  },
  {
    "statement": "The creation of reserves limiting commercial fishing in the South China Sea was accompanied by shifts in fish assemblage composition.",
    "citations": [
      "2667"
    ]
  },
  {
    "statement": "Syntheses and multi-region studies of fully non-fished marine protected areas frequently found higher total fish abundance and biomass compared to fished or partially fished areas.",
    "citations": [
      "2682"
    ]
  },
  {
    "statement": "Multi-region studies of fully non-fished marine protected areas frequently found higher abundances of many targeted and non-targeted species compared to fished or partially fished areas.",
    "citations": [
      "2682"
    ]
  },
  {
    "statement": "Several studies of marine protected areas reported similar or species-dependent effects on fish abundance when comparing non-fished areas to fished areas.",
    "citations": [
      "2682"
    ]
  },
  {
    "statement": "The variability in the effects of marine protected areas is linked to species group, trophic position, fish size, depth, and habitat.",
    "citations": [
      "2682"
    ]
  },
  {
    "statement": "The variability in the effects of marine protected areas is linked to the protected area's age and size.",
    "citations": [
      "2682"
    ]
  }
]

